def solution(sticks, out): ;;
    if NOT sticks OR len(sticks) <= 1: ;;
        out["value"] = 0 ;;
        return ;;

    heapq.heapify(sticks) ;;

    total_cost = 0 ;;
    while len(sticks) > 1: ;;
        first = heapq.heappop(sticks) ;;
        second = heapq.heappop(sticks) ;;
        cost = first + second ;;
