    current_min_costs = [INF] * (n + 1)
    total_cost = 0
    members_arrived = 0
    ptr = 0
    for d in range(1, max_d + 1):
        while ptr < len(flights_to) and flights_to[ptr][0] == d:
            day, f, t, c = flights_to[ptr]
            if c < current_min_costs[f]:
                if current_min_costs[f] == INF:
                    members_arrived += 1
                else:
                    total_cost -= current_min_costs[f]
                current_min_costs[f] = c
                total_cost += c
            ptr += 1
        if members_arrived == n:
            min_arr_cost[d] = total_cost
        else:
            min_arr_cost[d] = INF

    # Precompute min_dep_cost
    current_min_costs = [INF] * (n + 1)
    total_cost = 0
    members_departed = 0
    ptr = 0
    for d in range(max_d, 0, -1):
