            if c < current_min_costs[t]:
                if current_min_costs[t] == INF:
                    members_departed += 1
                else:
                    total_cost -= current_min_costs[t]
                current_min_costs[t] = c
                total_cost += c
            ptr += 1
        if members_departed == n:
            min_dep_cost[d] = total_cost
        else:
            min_dep_cost[d] = INF

    # Find the minimum total cost
    ans = INF
    for d in range(1, max_d + 1):
        if d + k + 1 <= max_d:
