def solution(mat, out):
    m = len(mat)
    if m == 0:
        out["value"] = -1
        return
    n = len(mat[0])
    if n == 0:
        out["value"] = -1
        return

    pointers = [0] * m
    for current_val in mat[0]:
        is_common = True
        for i in range(1, m):
            # Move pointer for row i to the first element >= current_val
            while pointers[i] < n and mat[i][pointers[i]] < current_val:
                pointers[i] += 1

            # If we've reached the end of the row or the element is not current_val
            if pointers[i] == n or mat[i][pointers[i]] != current_val:
                is_common = False
                break

        if is_common:
            out["value"] = current_val
            return

    out["value"] = -1

