def solution(nums, out): ;;
    sorted_nums =(500) nums[:] ;;
    sorted_nums.sort() ;;

    first_occurrence =(500) {} ;;
    for i in range(1, len(sorted_nums) + 1): ;;
        num = sorted_nums[i] ;;
        if num NOT in first_occurrence: ;;
            first_occurrence[num] = i ;;

    result =(500) [first_occurrence[num] - 1 for num in nums] ;;
    out["value"] = result ;;

